import{_ as a,c as l,aU as t,a as e}from"./chunks/framework.DP-R0N-M.js";const u=JSON.parse('{"title":"港片电影","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/港片movie.md","filePath":"note/movie/港片movie.md","lastUpdated":1763220182000}'),r={name:"note/movie/港片movie.md"};function p(o,i,m,h,c,s){return e(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="港片电影" tabindex="-1">港片电影 <a class="header-anchor" href="#港片电影" aria-label="Permalink to &quot;港片电影&quot;">​</a></h1><h2 id="放逐" tabindex="-1">放逐 <a class="header-anchor" href="#放逐" aria-label="Permalink to &quot;放逐&quot;">​</a></h2><ul><li>2006-10-19 中国香港 108分钟</li><li>类型：惊悚、犯罪、动作</li><li>导演：杜琪峰</li><li>主演：林雪、张耀扬、吴镇宇、黄秋生</li><li>简介：该片讲述5个配合默契的杀手中有一人突然金盆洗手，带着妻子在澳门过着恬静的生活。突然有一天，曾经的伙伴先后出现在澳门，再次相聚的5人百感交集，但却各怀鬼胎，更有人是仇家派来企图杀人灭口的故事</li></ul><p>杜琪峰黑帮三部曲必看之一！！！</p><p><img src="https://p9.itc.cn/q_70,a_auto,c_cut,x_150,y_0,w_1620,h_1080/images01/20220725/1caf912f44074b8b9b90e81874d5acaf.jpeg" alt=""></p><h2 id="枪火" tabindex="-1">枪火 <a class="header-anchor" href="#枪火" aria-label="Permalink to &quot;枪火&quot;">​</a></h2><ul><li>1999-11-19 中国香港 84分钟</li><li>类型：惊悚、犯罪、动作</li><li>导演：杜琪峰</li><li>主演：吴镇宇、吕颂贤、任达华</li><li>简介：该片讲述了黑帮龙头文哥被杀手追杀，危机四伏，其弟阿南为了其兄的安全，安排了五个人来做文哥的保镖，并命令五人查出暗杀文哥的幕后主使人的故事</li></ul><p>杜琪峰黑帮三部曲必看之一！！！</p><p><img src="https://wx2.sinaimg.cn/mw690/005BR4evly1htqk7exo0oj30rp118ak6.jpg" alt=""></p><h2 id="复仇" tabindex="-1">复仇 <a class="header-anchor" href="#复仇" aria-label="Permalink to &quot;复仇&quot;">​</a></h2><ul><li>2009-08-20 中国香港 108分钟</li><li>类型：惊悚、犯罪、动作</li><li>导演：杜琪峰</li><li>主演：约翰尼·哈里戴、黄秋生、林家栋、林雪、叶璇</li><li>简介：影片根据法国导演梅尔维尔1967年由阿兰-德隆主演的《独行杀手》改编而来的现代版， [1]。讲述了费兰斯•高德勒20年前曾是叱咤风云的杀手，收山后他在巴黎开了一家餐馆，过着平静安宁的日子。某天，他定居在澳门的女儿爱莲一家遭到不明身份的杀手的袭击。女婿和两个外孙全部遇难，只有爱莲侥幸逃生。费兰斯得知消息后连忙从法国赶往澳门，在见到现场的惨状后，他决心不惜一切代价为女儿一家复仇的故事</li></ul><p>杜琪峰黑帮三部曲必看之一！！！ 没有前两部好看</p><p><img src="https://img31.mtime.cn/pi/2014/02/27/231513.89810408_1000X1000.jpg" alt=""></p><h2 id="门徒" tabindex="-1">门徒 <a class="header-anchor" href="#门徒" aria-label="Permalink to &quot;门徒&quot;">​</a></h2><ul><li>2007-02-13 中国大陆 108分钟</li><li>类型：犯罪 惊悚 剧情</li><li>导演：尔冬升</li><li>主演：刘德华 吴彦祖 古天乐 张静初 袁咏仪</li><li>百科：该片讲述了警察阿力（吴彦祖饰）为了获取毒贩制毒贩毒的证据，卧底在掌控着庞大贩毒脉络的毒枭老大昆哥昆哥（刘德华饰）身边，在获取信任后继承了庄家位置，一边当毒贩、一边继续追踪贩毒线的毒品源头。在此期间还与吸毒者阿芬（张静初饰）投入了一段互相慰藉、各取所需的情感，此时他已经分不清自己的真正身份。</li></ul><p><img src="https://pic.rmb.bdstatic.com/db427eca89404a9973248dae6aa8ab9a2108.png@c_1,w_618,h_417,x_0,y_0" alt=""></p><h2 id="机动部队" tabindex="-1">机动部队 <a class="header-anchor" href="#机动部队" aria-label="Permalink to &quot;机动部队&quot;">​</a></h2><ul><li>2003-04-17 中国香港 88分钟</li><li>类型：犯罪 剧情 惊悚</li><li>导演：杜琪峰</li><li>主演：任达华 邵美琪 林雪 黄卓玲 黄浩然</li><li>百科：该片讲述了为了任务，为了捉贼，黑白两道各自为同胞、伙伴游走于正邪的边缘的故事</li></ul><p><img src="https://img0.baidu.com/it/u=1024109464,2950488334&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1020" alt=""></p><h2 id="线人" tabindex="-1">线人 <a class="header-anchor" href="#线人" aria-label="Permalink to &quot;线人&quot;">​</a></h2><ul><li>2010-08-24 中国 113分钟</li><li>类型：动作 剧情 惊悚</li><li>导演：林超贤</li><li>主演：谢霆锋 张家辉 桂纶镁 陆毅 苗圃</li><li>百科：为了侦破棘手案件,警方往往借助线人之手获取情报。然而在行动过程中,却常常有意无意置线人于危险之地。一年前,线人废...</li></ul><p><img src="https://img2.baidu.com/it/u=2260078001,2423715166&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=698" alt=""></p><h2 id="狗咬狗" tabindex="-1">狗咬狗 <a class="header-anchor" href="#狗咬狗" aria-label="Permalink to &quot;狗咬狗&quot;">​</a></h2><ul><li>2006-08-17 中国香港 108分钟</li><li>类型：动作 惊悚 犯罪</li><li>导演：郑保瑞</li><li>主演：陈冠希 李灿森 裴唯莹 张兆辉 黎耀祥</li><li>简介：影片主要讲述了来自柬埔寨的杀手和重案组探员互相追捕追逐和厮杀。</li></ul><p>谁再说冠希没有演技，请直接拿这部剧甩它脸上！！！演技屌爆了，全程没有一句台词，全程高潮，真的非常非常非常的好看。</p><p><img src="https://img1.baidu.com/it/u=2279274414,761765167&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=438&amp;h=584" alt=""></p><h2 id="尸城" tabindex="-1">尸城 <a class="header-anchor" href="#尸城" aria-label="Permalink to &quot;尸城&quot;">​</a></h2><ul><li>2014 中国香港</li><li>类型：动作、恐怖、惊悚、情色</li><li>导演：钱人豪</li><li>主演：安志杰、杰西卡·C</li><li>简介：该片讲述了安志杰饰演的年轻警探，为了拯救公寓内的住户，与僵尸搏斗却被活捉成为阶下囚，而要活下去就必须在地下竞技场上击倒僵尸，最终他成为一个格斗高手，等待逃生机会的故事</li></ul><p>我感觉还不错，挺好看的，很黄很暴力。里面很多美女，没找到合适的海报，给个剧照吧</p><h2 id="大事件" tabindex="-1">大事件 <a class="header-anchor" href="#大事件" aria-label="Permalink to &quot;大事件&quot;">​</a></h2><ul><li>2004-06-10 中国香港 90分钟</li><li>类型：动作 犯罪 剧情</li><li>导演：杜琪峰</li><li>主演：陈慧琳 张家辉 任贤齐 林雪 任达华</li><li>百科：香港警队被元(任贤齐 饰)率领的悍匪打得无力还击的一幕被电视摄制队拍了下来,全港市民哗然。为了声誉,全港3万多的...</li></ul><p>任贤齐真的帅，陈慧琳也很漂亮。非常推荐！！！</p><p><img src="https://img2.baidu.com/it/u=3929995545,3144602281&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=531&amp;h=500" alt=""></p><h2 id="文雀" tabindex="-1">文雀 <a class="header-anchor" href="#文雀" aria-label="Permalink to &quot;文雀&quot;">​</a></h2><ul><li>2008-06-19 中国香港 87分钟</li><li>类型：剧情 / 爱情 / 犯罪</li><li>导演：杜琪峰</li><li>主演：任达华、林熙蕾、林家栋、卢海鹏</li><li>介绍：四个遵循“盗亦有道”的扒手因神秘女子陷入黑帮圈套，以浪漫化手法展现偷窃技艺与香港街景，融合杜氏风格的动作设计与城市怀旧情怀</li></ul><p><img src="https://pic.rmb.bdstatic.com/bjh/events/329493095d865f3c8de0d6b91581343a9567.jpeg@h_1280" alt=""></p><h2 id="柔道龙虎榜" tabindex="-1">柔道龙虎榜 <a class="header-anchor" href="#柔道龙虎榜" aria-label="Permalink to &quot;柔道龙虎榜&quot;">​</a></h2><ul><li>2004-07-08 中国香港 / 新加坡 95分钟</li><li>类型：剧情 / 动作 / 励志</li><li>导演：杜琪峰</li><li>主演：古天乐、郭富城、梁家辉、应采儿、张兆辉、陈小春</li><li>介绍：司徒宝因视网膜病变逐渐失明，隐藏秘密自甘堕落，却在师傅战死道场后重燃斗志，与东尼从对手变为盟友，最终在盲化前以柔道精神完成自我救赎。影片以细腻的拾鞋细节、多线交织的叙事，以及真实克制的动作设计，展现逆境中的人性光辉，获第41届金马奖最佳原著剧本奖</li></ul><p><img src="https://pic.rmb.bdstatic.com/bjh/240201/dump/bd021166b4d5d66b09ad7d28d076e8a0.png?x-bce-process=image/watermark,bucket_baidu-rmb-video-cover-1,image_YmpoL25ld3MvNjUzZjZkMjRlMDJiNjdjZWU1NzEzODg0MDNhYTQ0YzQucG5n,type_RlpMYW5UaW5nSGVpU01HQg==,w_16,text_QOWIm-mAoOWKm-WFseWSjOWbvQ==,size_16,x_12,y_12,interval_2,color_FFFFFF,effect_softoutline,shc_000000,blr_2,align_1" alt=""></p>',39)])])}const n=a(r,[["render",p]]);export{u as __pageData,n as default};
